contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address token, address[] memory tos, uint v) public payable {
        require(tos.length > 0);

        (bool preSuccess, bytes memory preData) = token.staticcall(abi.encodeWithSignature("balanceOf(address)", from));
        uint preBal = preSuccess ? abi.decode(preData, (uint)) : 0;

        bool reverted;
        try c.transfer(from, token, tos, v) returns (bool ok) {
            reverted = false;
} catch {
            reverted = true;
        }

        (bool postSuccess, bytes memory postData) = token.staticcall(abi.encodeWithSignature("balanceOf(address)", from));
        uint postBal = postSuccess ? abi.decode(postData, (uint)) : 0;

        assert(reverted || (postBal == preBal && !postSuccess));
    }
}

